const debRemoteUnverified = `-- name: DebRemoteUnverified :many
SELECT dir, document
  FROM deb_remote_releases
 WHERE repo_id = $1::bigint AND document <> 'absent' AND verified_by IS NULL
 ORDER BY dir, document
`

type DebRemoteUnverifiedRow struct {
	Dir      string
	Document string
}

// The stored documents that no key verifies now, for the re-verification of a remote that has keys.
func (q *Queries) DebRemoteUnverified(ctx context.Context, repoID int64) ([]DebRemoteUnverifiedRow, error) {
	rows, err := q.db.Query(ctx, debRemoteUnverified, repoID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DebRemoteUnverifiedRow{}
	for rows.Next() {
		var i DebRemoteUnverifiedRow
		if err := rows.Scan(&i.Dir, &i.Document); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

